PRAGMA foreign_keys = ON;

CREATE TRIGGER auto_grant_coin_achievement_rewards AFTER UPDATE OF games_played, wins, rating ON players BEGIN UPDATE players SET online_coins = online_coins + 50 WHERE id = NEW.id AND NEW.wins >= 1 AND NOT EXISTS ( SELECT 1 FROM coin_ledger WHERE idempotency_key = 'achievement:' || NEW.id || ':first_win' ); INSERT OR IGNORE INTO coin_ledger ( id, player_id, amount, balance_after, reason, reference_type, reference_id, idempotency_key, metadata_json, created_at ) SELECT lower(hex(randomblob(16))), NEW.id, 50, (SELECT online_coins FROM players WHERE id = NEW.id), 'achievement_reward', 'achievement', 'first_win', 'achievement:' || NEW.id || ':first_win', json_object('tier', 'bronze'), NEW.updated_at WHERE NEW.wins >= 1; INSERT OR IGNORE INTO reward_claims ( id, player_id, reward_type, reward_key, amount, status, prepared_at, claimed_at ) SELECT lower(hex(randomblob(16))), NEW.id, 'achievement_reward', 'first_win', 50, 'claimed', NEW.updated_at, NEW.updated_at WHERE NEW.wins >= 1; UPDATE players SET online_coins = online_coins + 100 WHERE id = NEW.id AND NEW.wins >= 10 AND NOT EXISTS ( SELECT 1 FROM coin_ledger WHERE idempotency_key = 'achievement:' || NEW.id || ':wins_10' ); INSERT OR IGNORE INTO coin_ledger ( id, player_id, amount, balance_after, reason, reference_type, reference_id, idempotency_key, metadata_json, created_at ) SELECT lower(hex(randomblob(16))), NEW.id, 100, (SELECT online_coins FROM players WHERE id = NEW.id), 'achievement_reward', 'achievement', 'wins_10', 'achievement:' || NEW.id || ':wins_10', json_object('tier', 'silver'), NEW.updated_at WHERE NEW.wins >= 10; INSERT OR IGNORE INTO reward_claims ( id, player_id, reward_type, reward_key, amount, status, prepared_at, claimed_at ) SELECT lower(hex(randomblob(16))), NEW.id, 'achievement_reward', 'wins_10', 100, 'claimed', NEW.updated_at, NEW.updated_at WHERE NEW.wins >= 10; UPDATE players SET online_coins = online_coins + 100 WHERE id = NEW.id AND NEW.games_played >= 25 AND NOT EXISTS ( SELECT 1 FROM coin_ledger WHERE idempotency_key = 'achievement:' || NEW.id || ':games_25' ); INSERT OR IGNORE INTO coin_ledger ( id, player_id, amount, balance_after, reason, reference_type, reference_id, idempotency_key, metadata_json, created_at ) SELECT lower(hex(randomblob(16))), NEW.id, 100, (SELECT online_coins FROM players WHERE id = NEW.id), 'achievement_reward', 'achievement', 'games_25', 'achievement:' || NEW.id || ':games_25', json_object('tier', 'silver'), NEW.updated_at WHERE NEW.games_played >= 25; INSERT OR IGNORE INTO reward_claims ( id, player_id, reward_type, reward_key, amount, status, prepared_at, claimed_at ) SELECT lower(hex(randomblob(16))), NEW.id, 'achievement_reward', 'games_25', 100, 'claimed', NEW.updated_at, NEW.updated_at WHERE NEW.games_played >= 25; UPDATE players SET online_coins = online_coins + 250 WHERE id = NEW.id AND NEW.wins >= 50 AND NOT EXISTS ( SELECT 1 FROM coin_ledger WHERE idempotency_key = 'achievement:' || NEW.id || ':wins_50' ); INSERT OR IGNORE INTO coin_ledger ( id, player_id, amount, balance_after, reason, reference_type, reference_id, idempotency_key, metadata_json, created_at ) SELECT lower(hex(randomblob(16))), NEW.id, 250, (SELECT online_coins FROM players WHERE id = NEW.id), 'achievement_reward', 'achievement', 'wins_50', 'achievement:' || NEW.id || ':wins_50', json_object('tier', 'gold'), NEW.updated_at WHERE NEW.wins >= 50; INSERT OR IGNORE INTO reward_claims ( id, player_id, reward_type, reward_key, amount, status, prepared_at, claimed_at ) SELECT lower(hex(randomblob(16))), NEW.id, 'achievement_reward', 'wins_50', 250, 'claimed', NEW.updated_at, NEW.updated_at WHERE NEW.wins >= 50; UPDATE players SET online_coins = online_coins + 250 WHERE id = NEW.id AND NEW.rating >= 1200 AND NOT EXISTS ( SELECT 1 FROM coin_ledger WHERE idempotency_key = 'achievement:' || NEW.id || ':rating_1200' ); INSERT OR IGNORE INTO coin_ledger ( id, player_id, amount, balance_after, reason, reference_type, reference_id, idempotency_key, metadata_json, created_at ) SELECT lower(hex(randomblob(16))), NEW.id, 250, (SELECT online_coins FROM players WHERE id = NEW.id), 'achievement_reward', 'achievement', 'rating_1200', 'achievement:' || NEW.id || ':rating_1200', json_object('tier', 'gold'), NEW.updated_at WHERE NEW.rating >= 1200; INSERT OR IGNORE INTO reward_claims ( id, player_id, reward_type, reward_key, amount, status, prepared_at, claimed_at ) SELECT lower(hex(randomblob(16))), NEW.id, 'achievement_reward', 'rating_1200', 250, 'claimed', NEW.updated_at, NEW.updated_at WHERE NEW.rating >= 1200; UPDATE players SET online_coins = online_coins + 500 WHERE id = NEW.id AND NEW.rating >= 1500 AND NOT EXISTS ( SELECT 1 FROM coin_ledger WHERE idempotency_key = 'achievement:' || NEW.id || ':rating_1500' ); INSERT OR IGNORE INTO coin_ledger ( id, player_id, amount, balance_after, reason, reference_type, reference_id, idempotency_key, metadata_json, created_at ) SELECT lower(hex(randomblob(16))), NEW.id, 500, (SELECT online_coins FROM players WHERE id = NEW.id), 'achievement_reward', 'achievement', 'rating_1500', 'achievement:' || NEW.id || ':rating_1500', json_object('tier', 'platinum'), NEW.updated_at WHERE NEW.rating >= 1500; INSERT OR IGNORE INTO reward_claims ( id, player_id, reward_type, reward_key, amount, status, prepared_at, claimed_at ) SELECT lower(hex(randomblob(16))), NEW.id, 'achievement_reward', 'rating_1500', 500, 'claimed', NEW.updated_at, NEW.updated_at WHERE NEW.rating >= 1500; UPDATE players SET online_coins = online_coins + 1000 WHERE id = NEW.id AND NEW.wins >= 250 AND NOT EXISTS ( SELECT 1 FROM coin_ledger WHERE idempotency_key = 'achievement:' || NEW.id || ':wins_250' ); INSERT OR IGNORE INTO coin_ledger ( id, player_id, amount, balance_after, reason, reference_type, reference_id, idempotency_key, metadata_json, created_at ) SELECT lower(hex(randomblob(16))), NEW.id, 1000, (SELECT online_coins FROM players WHERE id = NEW.id), 'achievement_reward', 'achievement', 'wins_250', 'achievement:' || NEW.id || ':wins_250', json_object('tier', 'milestone'), NEW.updated_at WHERE NEW.wins >= 250; INSERT OR IGNORE INTO reward_claims ( id, player_id, reward_type, reward_key, amount, status, prepared_at, claimed_at ) SELECT lower(hex(randomblob(16))), NEW.id, 'achievement_reward', 'wins_250', 1000, 'claimed', NEW.updated_at, NEW.updated_at WHERE NEW.wins >= 250; END;
